using Microsoft.Win32;using System.Text.Json;using System.Windows;using System.Windows.Threading;using TAR.SoundSystem.Models;using TAR.SoundSystem.Services;
namespace TAR.SoundSystem;
public partial class MainWindow:Window{readonly EngineService engine=new();readonly DispatcherTimer timer=new(){Interval=TimeSpan.FromMilliseconds(50)};
 void RefreshDevices(){MidiCombo.ItemsSource=engine.MidiInputs;if(MidiCombo.Items.Count>0)MidiCombo.SelectedIndex=0;AudioCombo.ItemsSource=engine.AudioOutputs;if(AudioCombo.Items.Count>0)AudioCombo.SelectedIndex=0;}
 public MainWindow(){InitializeComponent();ChannelGrid.ItemsSource=engine.Channels;RefreshDevices();engine.StatusChanged+=x=>Dispatcher.Invoke(()=>StatusText.Text=x);engine.MidiReceived+=m=>Dispatcher.Invoke(()=>MidiMonitor.Text=$"MIDI 0x{m:X8} CH:{(m&15)+1}");timer.Tick+=(_,_)=>{PeakMeter.Value=engine.Peak;LufsReadout.Text=$"M: {engine.MomentaryLufs:0.0} LUFS | I: {engine.IntegratedLufs:0.0} LUFS";CompressionReadout.Text=$"Gain Reduction: {engine.GainReductionDb:0.0} dB";};timer.Start();Closed+=(_,_)=>engine.Dispose();}
 void BrowseSoundFont_Click(object s,RoutedEventArgs e){var d=new OpenFileDialog{Filter="SoundFont|*.sf2"};if(d.ShowDialog()==true){engine.LoadSoundFont(d.FileName);SoundFontPath.Text=d.FileName;}}
 void Start_Click(object s,RoutedEventArgs e){if(MidiCombo.SelectedIndex<0||!File.Exists(SoundFontPath.Text)){MessageBox.Show("เลือก MIDI และ SoundFont ก่อน");return;}if(AudioCombo.SelectedItem is not AudioOutputInfo a){MessageBox.Show("เลือก Sound Card Output ก่อน");return;}engine.Start(MidiCombo.SelectedIndex,a.Id);}void Stop_Click(object s,RoutedEventArgs e)=>engine.Stop();void Panic_Click(object s,RoutedEventArgs e)=>engine.Panic();
 void EqChanged(object s,RoutedPropertyChangedEventArgs<double> e){if(IsInitialized)engine.SetEq((float)LowSlider.Value,(float)MidSlider.Value,(float)HighSlider.Value);}void MasterChanged(object s,RoutedPropertyChangedEventArgs<double> e){if(IsInitialized)engine.SetMaster((float)MasterSlider.Value);}
 void CompressorChanged(object s,RoutedEventArgs e){if(!IsInitialized)return;engine.SetCompressor(CompEnabled.IsChecked==true,(float)ThresholdSlider.Value,(float)RatioSlider.Value,(float)AttackSlider.Value,(float)ReleaseSlider.Value,(float)MakeupSlider.Value);}
 void ResetLufs_Click(object s,RoutedEventArgs e)=>engine.ResetLufs();
 void AddVst_Click(object s,RoutedEventArgs e){var d=new OpenFileDialog{Filter="VST3 Plug-in|*.vst3",CheckFileExists=true};if(d.ShowDialog()!=true)return;try{var n=engine.LoadVst3(d.FileName);VstList.Items.Add(n);}catch(Exception ex){MessageBox.Show(ex.ToString(),"โหลด VST3 ไม่สำเร็จ");}}

 Registration Snap()=>new(){SoundFontPath=SoundFontPath.Text,Low=(float)LowSlider.Value,Mid=(float)MidSlider.Value,High=(float)HighSlider.Value,Master=(float)MasterSlider.Value,Channels=engine.Channels.Select(c=>new ChannelState{Channel=c.Channel,Volume=c.Volume,Pan=c.Pan,Program=c.Program,Transpose=c.Transpose,Mute=c.Mute,Solo=c.Solo}).ToList()};
 void Save_Click(object s,RoutedEventArgs e){var d=new SaveFileDialog{Filter="TAR Registration|*.tarreg.json",FileName="live-set.tarreg.json"};if(d.ShowDialog()==true)File.WriteAllText(d.FileName,JsonSerializer.Serialize(Snap(),new JsonSerializerOptions{WriteIndented=true}));}
 void Load_Click(object s,RoutedEventArgs e){var d=new OpenFileDialog{Filter="TAR Registration|*.tarreg.json"};if(d.ShowDialog()!=true)return;var x=JsonSerializer.Deserialize<Registration>(File.ReadAllText(d.FileName));if(x==null)return;LowSlider.Value=x.Low;MidSlider.Value=x.Mid;HighSlider.Value=x.High;MasterSlider.Value=x.Master;foreach(var a in x.Channels){var c=engine.Channels[a.Channel-1];c.Volume=a.Volume;c.Pan=a.Pan;c.Program=a.Program;c.Transpose=a.Transpose;c.Mute=a.Mute;c.Solo=a.Solo;}if(File.Exists(x.SoundFontPath)){engine.LoadSoundFont(x.SoundFontPath);SoundFontPath.Text=x.SoundFontPath;}engine.ApplyMixer();}
}